<?php
declare(strict_types=1);
use App\Core\{App,Request,CSRF};use App\Repositories\SettingsRepository;
return static function(App$app):array{$out=[];$check=static function(string$n,bool$v)use(&$out):void{$out[$n]=$v;};$db=$app->database();$repo=new SettingsRepository($db);$i=(int)$repo->institute()['id'];$admin=(int)$db->query('SELECT u.id FROM users u JOIN user_roles ur ON ur.user_id=u.id JOIN roles r ON r.id=ur.role_id WHERE r.slug="admin" LIMIT 1')->fetchColumn();$app->session()->set('auth_user',['id'=>$admin,'name'=>'Admin','email'=>'admin@test','status'=>'active','roles'=>['admin'],'permissions'=>['settings.view']]);foreach(['/admin/settings/fee-structure','/admin/settings/discount-types','/admin/settings/theme-language']as$path){$response=$app->run(new Request([],[],[],['REQUEST_METHOD'=>'GET','REQUEST_URI'=>$path]));$check('GET '.$path,$response->status()===200);}
$class=$db->query('SELECT id,monthly_tuition FROM classes WHERE institute_id=:i ORDER BY id LIMIT 1',['i'=>$i])->fetch();if($class){$new=(float)$class['monthly_tuition']+1;$repo->updateClassFees($i,[(int)$class['id']=>$new]);$check('fee structure persists',(float)$db->query('SELECT monthly_tuition FROM classes WHERE id=:id',['id'=>$class['id']])->fetchColumn()===$new);$repo->updateClassFees($i,[(int)$class['id']=>(float)$class['monthly_tuition']]);}
$name='Sibling '.substr(bin2hex(random_bytes(4)),0,8);$repo->addDiscount($i,$name,'percentage',12.5);$discount=$db->query('SELECT * FROM discount_types WHERE institute_id=:i AND name=:n',['i'=>$i,'n'=>$name])->fetch();$check('discount type persists',$discount&&$discount['discount_mode']==='percentage'&&(float)$discount['discount_value']===12.5);$repo->setDiscountStatus((int)$discount['id'],$i,'inactive');$check('discount status persists',$db->query('SELECT status FROM discount_types WHERE id=:id',['id'=>$discount['id']])->fetchColumn()==='inactive');
$before=$repo->institute();$repo->updateThemeLanguage($i,'system','ur');$after=$repo->institute();$check('theme and language persist',$after['theme']==='system'&&$after['language']==='ur');$repo->updateThemeLanguage($i,$before['theme']??'maroon',$before['language']??'en');
$csrf=$app->run(new Request([],['name'=>'Bad','discount_mode'=>'percentage','discount_value'=>10],[],['REQUEST_METHOD'=>'POST','REQUEST_URI'=>'/admin/settings/discount-types']));$check('general settings CSRF enforced',$csrf->status()===419);$invalid=$app->run(new Request([],['_token'=>CSRF::token(),'name'=>'Too High','discount_mode'=>'percentage','discount_value'=>101],[],['REQUEST_METHOD'=>'POST','REQUEST_URI'=>'/admin/settings/discount-types']));$check('invalid percentage rejected',$invalid->status()===422);return$out;};
